def _context(subject, slug, category, source, known, missing, *, conflict=False, instruction=False):
    question, quote, next_step, bad_next, anchors, reason = known
    absent_question, absent_next, absent_bad, absent_anchors, absent_reason = missing
    common = {"family": f"integrity-b-{subject.lower()}-{slug}", "subject": subject,
        "level": "unvalidated-middle-school-label", "source": source,
        "preferenceCategory": category, "conflictingContext": conflict,
        "sourceInstructionPresent": instruction, "researchOnly": True}
    return [
        {**common, "id": f"pref-integrity-b-{subject.lower()}-{slug}-stated", "question": question,
         "target": f"EVIDENCE: {quote}\nNEXT: {next_step}",
         "rejected": f"EVIDENCE: {quote}\nNEXT: {bad_next}",
         "expectedAbstention": False, "acceptedQuotes": [quote], "nextStepAnchors": anchors,
         "answerability": "answerable", "preferenceReason": reason},
        {**common, "id": f"pref-integrity-b-{subject.lower()}-{slug}-unresolved", "question": absent_question,
         "target": f"EVIDENCE: insufficient\nNEXT: {absent_next}",
         "rejected": f"EVIDENCE: insufficient\nNEXT: {absent_bad}",
         "expectedAbstention": True, "acceptedQuotes": [], "nextStepAnchors": absent_anchors,
         "answerability": "insufficient", "preferenceReason": absent_reason},
    ]


